#pragma once
inline constexpr wchar_t MainXaml[]=LR"xaml(
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Background="Transparent">
 <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
 <TitleBar x:Name="TitleBar" Title="Connecty" MinHeight="48" IsPaneToggleButtonVisible="True"><TitleBar.LeftHeader><Image x:Name="Logo" Width="32" Height="32" Margin="0,0,8,0"/></TitleBar.LeftHeader></TitleBar>
 <Grid Grid.Row="1"><Grid.ColumnDefinitions><ColumnDefinition x:Name="RailWidth" Width="208"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
  <Grid x:Name="Rail" Padding="10,12,10,12"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
   <Grid x:Name="RailHeader" Margin="12,0,2,12"><TextBlock x:Name="RailHeading" Text="Connections" FontWeight="SemiBold" FontSize="13" VerticalAlignment="Center"/><Button x:Name="Add" HorizontalAlignment="Right" Style="{ThemeResource SubtleButtonStyle}" ToolTipService.ToolTip="New connection" AutomationProperties.Name="New connection"><FontIcon Glyph="&#xE710;" FontSize="14" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/></Button></Grid>
   <ListView x:Name="Profiles" Grid.Row="1" SelectionMode="Single" Background="Transparent" BorderThickness="0" AutomationProperties.Name="Connections"/>
   <StackPanel x:Name="RailFooter" Grid.Row="2" Spacing="4" Margin="10,12,4,0"><TextBlock x:Name="Summary" Margin="0,0,0,6" FontSize="12" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/><Button x:Name="Settings" AutomationProperties.Name="Settings" Style="{ThemeResource SubtleButtonStyle}" HorizontalAlignment="Stretch" HorizontalContentAlignment="Left"><StackPanel Orientation="Horizontal" Spacing="10"><FontIcon Glyph="&#xE713;" FontSize="16" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock x:Name="SettingsText" Text="Settings" FontSize="13"/></StackPanel></Button></StackPanel>
  </Grid>
  <Border Grid.Column="1" Margin="0,4,8,8" CornerRadius="12" Background="{ThemeResource LayerFillColorDefaultBrush}" BorderBrush="{ThemeResource CardStrokeColorDefaultBrush}" BorderThickness="1">
   <Grid Padding="24,22,24,18">
    <Grid x:Name="Empty"><StackPanel MaxWidth="300" HorizontalAlignment="Center" VerticalAlignment="Center" Spacing="16"><FontIcon Glyph="&#xE968;" FontSize="36" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock Text="Your connections, always on." FontSize="23" FontWeight="SemiBold" TextWrapping="Wrap" TextAlignment="Center"/><TextBlock Text="Add a server to get started." TextAlignment="Center" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/><Button x:Name="FirstAdd" Content="New connection" Style="{ThemeResource AccentButtonStyle}" HorizontalAlignment="Center"/></StackPanel></Grid>
    <Grid x:Name="Details" Visibility="Collapsed"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
     <Grid Margin="0,0,0,20"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Spacing="5"><TextBlock x:Name="Name" FontSize="25" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/><StackPanel Orientation="Horizontal" Spacing="7"><FontIcon x:Name="DirectionIcon" Glyph="&#xE8AB;" FontSize="12" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock x:Name="Direction" FontSize="12" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></StackPanel></StackPanel><Button x:Name="Edit" Grid.Column="1" VerticalAlignment="Top" Style="{ThemeResource SubtleButtonStyle}" ToolTipService.ToolTip="Edit connection" AutomationProperties.Name="Edit connection"><FontIcon Glyph="&#xE70F;" FontSize="16" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/></Button></Grid>
)xaml"
LR"xaml(
     <Border Grid.Row="1" Padding="18" CornerRadius="10" Background="{ThemeResource CardBackgroundFillColorDefaultBrush}" BorderBrush="{ThemeResource CardStrokeColorDefaultBrush}" BorderThickness="1"><StackPanel Spacing="18">
      <StackPanel Orientation="Horizontal" Spacing="12"><Border Width="36" Height="36" CornerRadius="9" Background="{ThemeResource SubtleFillColorSecondaryBrush}"><FontIcon x:Name="StateIcon" Glyph="&#xE73E;" FontSize="18"/></Border><StackPanel Spacing="3" VerticalAlignment="Center"><TextBlock x:Name="State" FontWeight="SemiBold" FontSize="14"/><TextBlock x:Name="Age" FontSize="12" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></StackPanel></StackPanel>
      <Border Height="1" Background="{ThemeResource DividerStrokeColorDefaultBrush}"/>
      <Grid ColumnSpacing="12"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
       <StackPanel Spacing="8"><TextBlock Text="Listen" FontSize="11" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/><StackPanel Orientation="Horizontal" Spacing="8"><FontIcon x:Name="SourceIcon" Glyph="&#xE968;" FontSize="17" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock x:Name="Host" FontSize="13" FontWeight="SemiBold" TextTrimming="CharacterEllipsis" MaxWidth="150"/></StackPanel><TextBlock x:Name="RemotePort" FontSize="12" FontFamily="Consolas" TextTrimming="CharacterEllipsis" IsTextSelectionEnabled="True" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></StackPanel>
       <StackPanel Grid.Column="1" Spacing="8"><TextBlock Text="Forward to" FontSize="11" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/><StackPanel Orientation="Horizontal" Spacing="8"><FontIcon x:Name="TargetIcon" Glyph="&#xE7F4;" FontSize="17" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock x:Name="TargetHost" FontSize="13" FontWeight="SemiBold" TextTrimming="CharacterEllipsis" MaxWidth="150"/></StackPanel><TextBlock x:Name="Target" FontSize="12" FontFamily="Consolas" TextTrimming="CharacterEllipsis" IsTextSelectionEnabled="True" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></StackPanel>
      </Grid>
     </StackPanel></Border>
     <InfoBar x:Name="Detail" Grid.Row="2" Margin="0,10,0,0" IsOpen="False" IsClosable="False" Severity="Warning"/>
     <Grid Grid.Row="3" Margin="0,16,0,18"><StackPanel Orientation="Horizontal" Spacing="8"><Button x:Name="Connect" MinWidth="118" CornerRadius="6"><StackPanel Orientation="Horizontal" Spacing="8"><FontIcon x:Name="ConnectIcon" Glyph="&#xE7E8;" FontSize="14"/><TextBlock x:Name="ConnectText" Text="Connect"/></StackPanel></Button><Button x:Name="Reconnect" AutomationProperties.Name="Reconnect" Style="{ThemeResource SubtleButtonStyle}"><StackPanel Orientation="Horizontal" Spacing="8"><FontIcon Glyph="&#xE72C;" FontSize="14" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock Text="Reconnect"/></StackPanel></Button></StackPanel><Button x:Name="Delete" HorizontalAlignment="Right" Style="{ThemeResource SubtleButtonStyle}" ToolTipService.ToolTip="Remove connection" AutomationProperties.Name="Remove connection"><FontIcon Glyph="&#xE74D;" FontSize="15" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></Button></Grid>
     <Grid Grid.Row="4"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions><Grid Margin="0,0,0,8"><StackPanel Orientation="Horizontal" Spacing="8" VerticalAlignment="Center"><FontIcon Glyph="&#xE81C;" VerticalAlignment="Center" FontSize="14" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock Text="Activity" VerticalAlignment="Center" FontSize="13" FontWeight="SemiBold"/></StackPanel><Button x:Name="OpenLog" HorizontalAlignment="Right" Style="{ThemeResource SubtleButtonStyle}" Padding="8,5" FontSize="12" AutomationProperties.Name="Copy activity"><StackPanel Orientation="Horizontal" Spacing="6"><FontIcon Glyph="&#xE8C8;" FontSize="12"/><TextBlock Text="Copy"/></StackPanel></Button></Grid><TextBlock x:Name="NoLogs" Grid.Row="1" Text="Activity will appear here." Margin="0,10,0,0" FontSize="12" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/><ListView x:Name="Logs" Grid.Row="1" SelectionMode="None" IsItemClickEnabled="False" IsTabStop="False" Background="Transparent" BorderThickness="0" Padding="0" AutomationProperties.Name="Recent activity"/></Grid>
    </Grid>
   </Grid>
  </Border>
 </Grid>
</Grid>)xaml";
inline constexpr wchar_t EditorXaml[]=LR"xaml(
<ScrollViewer xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" MaxHeight="470"><StackPanel Spacing="12" MinWidth="390" Padding="0,0,10,6">
 <InfoBar x:Name="ValidationMessage" IsOpen="False" IsClosable="False" Severity="Error"/>
 <Grid ColumnSpacing="12"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBox x:Name="Name" Header="Name" PlaceholderText="Home PC" MaxLength="80"/><TextBox x:Name="Host" Grid.Column="1" Header="SSH server" PlaceholderText="Host or config alias" MaxLength="253"/></Grid>
 <ComboBox x:Name="Direction" Header="Tunnel direction" HorizontalAlignment="Stretch"><ComboBoxItem Content="Reverse forwarding"/><ComboBoxItem Content="Local forwarding"/></ComboBox>
 <Grid ColumnSpacing="12"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="110"/></Grid.ColumnDefinitions><TextBox x:Name="Target" Header="Destination address"/><NumberBox x:Name="TargetPort" Grid.Column="1" Header="Port" Minimum="1" Maximum="65535" SpinButtonPlacementMode="Compact"/></Grid>
 <NumberBox x:Name="RemotePort" Header="Listening port" Minimum="1" Maximum="65535" SpinButtonPlacementMode="Compact"/>
 <Grid ColumnSpacing="16" Margin="0,4,0,4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><ToggleSwitch x:Name="Retry" Header="Auto-reconnect"/><ToggleSwitch x:Name="Auto" Grid.Column="1" Header="Connect on start"/></Grid>
 <Expander Header="SSH identity" HorizontalAlignment="Stretch" HorizontalContentAlignment="Stretch"><StackPanel Spacing="12"><TextBox x:Name="Hostname" Header="Hostname override" PlaceholderText="Uses SSH config if empty"/><TextBox x:Name="User" Header="Username"/><NumberBox x:Name="Port" Header="SSH port (0 = config)" Minimum="0" Maximum="65535"/><TextBox x:Name="Identity" Header="Private key file" PlaceholderText="C:\Users\you\.ssh\id_ed25519"/><TextBox x:Name="KnownHosts" Header="Known hosts file" PlaceholderText="Uses ~/.ssh/known_hosts if empty"/></StackPanel></Expander>
 <Expander Header="Return-path check" HorizontalAlignment="Stretch" HorizontalContentAlignment="Stretch"><TextBox x:Name="Probe" Header="Command on server" PlaceholderText="Optional command returning exit code 0" MaxLength="2048"/></Expander>
</StackPanel></ScrollViewer>)xaml";
inline constexpr wchar_t PopupXaml[]=LR"xaml(
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Padding="12" Background="{ThemeResource AcrylicInAppFillColorDefaultBrush}"><StackPanel>
 <Grid Margin="4,2,2,12"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Orientation="Horizontal" Spacing="10"><Image x:Name="PopupLogo" Width="32" Height="32"/><StackPanel Spacing="2" VerticalAlignment="Center"><TextBlock Text="Connecty" FontSize="14" FontWeight="SemiBold"/><TextBlock x:Name="PopupCount" FontSize="11" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></StackPanel></StackPanel><Button x:Name="PopupSettings" Grid.Column="1" Style="{ThemeResource SubtleButtonStyle}" VerticalAlignment="Center" ToolTipService.ToolTip="Settings" AutomationProperties.Name="Settings"><FontIcon Glyph="&#xE713;" FontSize="16" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/></Button></Grid>
 <StackPanel x:Name="PopupRows" Spacing="4"/>
 <Border Height="1" Margin="4,10,4,6" Background="{ThemeResource DividerStrokeColorDefaultBrush}"/>
 <Button x:Name="PopupOpen" AutomationProperties.Name="Open Connecty" Style="{ThemeResource SubtleButtonStyle}" HorizontalAlignment="Stretch" HorizontalContentAlignment="Stretch" MinHeight="36"><Grid><StackPanel Orientation="Horizontal" Spacing="12"><FontIcon Glyph="&#xE8A7;" FontSize="16" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock Text="Open Connecty" FontSize="13"/></StackPanel><FontIcon Glyph="&#xE76C;" FontSize="10" HorizontalAlignment="Right" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/></Grid></Button>
 <Button x:Name="PopupPause" AutomationProperties.Name="Disconnect all" Style="{ThemeResource SubtleButtonStyle}" HorizontalAlignment="Stretch" HorizontalContentAlignment="Left" MinHeight="36"><StackPanel Orientation="Horizontal" Spacing="12"><FontIcon Glyph="&#xE7E8;" FontSize="16" Foreground="{ThemeResource AccentTextFillColorPrimaryBrush}"/><TextBlock Text="Disconnect all" FontSize="13"/></StackPanel></Button>
 <Button x:Name="PopupStop" AutomationProperties.Name="Stop agent" Style="{ThemeResource SubtleButtonStyle}" HorizontalAlignment="Stretch" HorizontalContentAlignment="Left" MinHeight="36" ToolTipService.ToolTip="Stop the background agent and disconnect all tunnels"><StackPanel Orientation="Horizontal" Spacing="12"><FontIcon Glyph="&#xE7E8;" FontSize="16" Foreground="{ThemeResource TextFillColorSecondaryBrush}"/><TextBlock Text="Stop agent" FontSize="13"/></StackPanel></Button>
</StackPanel></Border>)xaml";
